#!/usr/bin/env bash
# =========================================== # Secure RAG - Restore Script # =========================================== set -euo pipefail  BACKUP_DIR="${1:?Usage: ./scripts/restore.sh <backup_dir>}"  if [ ! -d "$BACKUP_DIR" ]; then   echo "Error: Backup directory not found: $BACKUP_DIR"   exit 1 fi  echo "Restoring from: $BACKUP_DIR" echo "WARNING: This will overwrite current data!" read -p "Continue? (y/N): " confirm if [ "$confirm" != "y" ] && [ "$confirm" != "Y" ]; then   echo "Restore cancelled"   exit 0 fi  # Restore PostgreSQL if [ -f "$BACKUP_DIR/postgres.dump" ]; then   echo "Restoring PostgreSQL..."   docker compose exec -T postgres pg_restore \     -U "${POSTGRES_USER:-secure_rag_user}" \     -d "${POSTGRES_DB:-secure_rag_db}" \     --clean --if-exists \     < "$BACKUP_DIR/postgres.dump"   echo "PostgreSQL restore complete" else   echo "No PostgreSQL backup found, skipping" fi  # Restore Redis if [ -f "$BACKUP_DIR/redis_dump.rdb" ]; then   echo "Restoring Redis..."   docker compose stop redis   docker compose cp "$BACKUP_DIR/redis_dump.rdb" redis:/data/dump.rdb   docker compose start redis   echo "Redis restore complete" else   echo "No Redis backup found, skipping" fi  echo "Restore complete at $(date)"
